1. #!/usr/bin/env node
2. /**
3.  * scripts/bounded-run.js
4.  *
5.  * Layer A of the bounded self-healing protocol (see .github/copilot-instructions.md
6.  * and docs/pipeline-plan.md Section 4).
7.  *
8.  * This is the ONLY way `npx playwright test <spec>` should ever be invoked during
9.  * an automated generate/heal session. It enforces a hard, stateful, 3-attempt cap
10.  * per spec file that survives across separate `copilot -p` invocations, pipeline
11.  * reruns, or a context-window reset mid-session — because the counter lives in a
12.  * JSON file on disk, not in the agent's memory.
13.  *
14.  * Usage:
15.  *   node scripts/bounded-run.js <path-to-spec>
16.  *
17.  * Exit codes:
18.  *   0 - test run passed. State file cleared.
19.  *   1 - test run failed, attempts remain (agent may heal and retry).
20.  *   2 - HARD STOP: attempts exhausted (>= 3). Row appended to
21.  *       unresolved-test-failures.csv. Do NOT call this again for this spec
22.  *       until the state file is manually cleared or the test starts passing.
23.  *
24.  * Layer B (structural enforcement) lives alongside this: the Copilot CLI
25.  * invocation denies `shell(npx playwright test:*)` and `shell(npm test:*)`
26.  * outright, so the agent has no path to bypass this wrapper within a live
27.  * session. Layer A (this script) is what makes the cap durable; Layer B is
28.  * what makes it un-bypassable. Neither alone is sufficient.
29.  */
30. 
31. 'use strict';
32. 
33. const fs = require('fs');
34. const path = require('path');
35. const { execSync } = require('child_process');
36. 
37. const MAX_ATTEMPTS = 3;
38. const HEALING_STATE_DIR = '.healing-state';
39. const UNRESOLVED_CSV = 'unresolved-test-failures.csv';
40. const CSV_HEADER = 'Timestamp, Test Name, Failing Step/Locator, Error Summary';
41. 
42. function fail(message) {
43.   console.error(`bounded-run: ${message}`);
44.   process.exit(2);
45. }
46. 
47. function specPathToStateFile(specPath) {
48.   // Sanitize the spec path into a flat, filesystem-safe filename so nested
49.   // directories under tests/ don't collide or require sub-directories here.
50.   const safeName = specPath.replace(/[\/\\]/g, '_');
51.   return path.join(HEALING_STATE_DIR, `${safeName}.json`);
52. }
53. 
54. function readState(stateFile) {
55.   if (!fs.existsSync(stateFile)) {
56.     return { attempts: 0 };
57.   }
58.   try {
59.     const raw = fs.readFileSync(stateFile, 'utf8');
60.     const parsed = JSON.parse(raw);
61.     if (typeof parsed.attempts !== 'number' || parsed.attempts < 0) {
62.       throw new Error('malformed attempts field');
63.     }
64.     return parsed;
65.   } catch (err) {
66.     // A corrupt state file must never silently reset the counter to 0 —
67.     // that would defeat the entire point of a durable cap. Fail loudly
68.     // instead and let a human decide whether to delete it.
69.     fail(
70.       `state file ${stateFile} exists but is unreadable/corrupt (${err.message}). ` +
71.       `Refusing to guess the attempt count. Inspect/delete it manually if this ` +
72.       `spec should be allowed to run again.`
73.     );
74.   }
75. }
76. 
77. function writeState(stateFile, state) {
78.   fs.mkdirSync(path.dirname(stateFile), { recursive: true });
79.   fs.writeFileSync(stateFile, JSON.stringify(state, null, 2) + '\n');
80. }
81. 
82. function extractErrorSummary(execError) {
83.   // execSync throws with stdout/stderr buffers attached. Playwright's default
84.   // reporter output is verbose; take a short, single-line-safe summary rather
85.   // than dumping the whole trace into the CSV.
86.   const raw = [
87.     execError.stdout ? execError.stdout.toString() : '',
88.     execError.stderr ? execError.stderr.toString() : '',
89.   ].join('\n');
90. 
91.   // Prefer the first line that looks like an actual assertion/error, not
92.   // Playwright's decorative box-drawing output.
93.   const lines = raw.split('\n').map((l) => l.trim()).filter(Boolean);
94.   const candidate = lines.find((l) =>
95.     /error|expect|timeout/i.test(l) && !/^[=─-]+$/.test(l)
96.   );
97. 
98.   const summary = (candidate || lines.slice(-1)[0] || 'Unknown failure (no output captured)')
99.     .replace(/,/g, ';') // commas would break the naive CSV format already in use
100.     .slice(0, 300);
101. 
102.   return summary;
103. }
104. 
105. function appendUnresolvedCsv(specPath, testName, failingStep, errorSummary) {
106.   const timestamp = new Date().toISOString();
107.   const row = [timestamp, testName, failingStep, errorSummary]
108.     .map((field) => String(field).replace(/,/g, ';'))
109.     .join(', ');
110. 
111.   const needsHeader = !fs.existsSync(UNRESOLVED_CSV);
112.   if (needsHeader) {
113.     fs.writeFileSync(UNRESOLVED_CSV, CSV_HEADER + '\n');
114.   }
115.   fs.appendFileSync(UNRESOLVED_CSV, row + '\n');
116.   console.error(`bounded-run: appended row to ${UNRESOLVED_CSV}`);
117. }
118. 
119. function main() {
120.   const specPath = process.argv[2];
121.   if (!specPath) {
122.     fail('usage: node scripts/bounded-run.js <path-to-spec>');
123.   }
124.   if (!fs.existsSync(specPath)) {
125.     fail(`spec file not found: ${specPath}`);
126.   }
127. 
128.   const stateFile = specPathToStateFile(specPath);
129.   const state = readState(stateFile);
130. 
131.   if (state.attempts >= MAX_ATTEMPTS) {
132.     console.error(`HARD STOP: ${specPath} already exhausted ${MAX_ATTEMPTS} heal attempts.`);
133.     appendUnresolvedCsv(
134.       specPath,
135.       specPath,
136.       'attempt-limit-exhausted',
137.       `No further heal attempts permitted after ${MAX_ATTEMPTS} tries. See prior CSV rows and .healing-state/ for history.`
138.     );
139.     process.exit(2);
140.   }
141. 
142.   state.attempts += 1;
143.   writeState(stateFile, state);
144.   console.log(`[HEAL ATTEMPT ${state.attempts}/${MAX_ATTEMPTS}]`);
145. 
146.   try {
147.     // Capture stdout/stderr (rather than 'inherit') so a single execution both
148.     // (a) streams to the CI log via the manual writes below, and (b) gives us
149.     // buffers to build a CSV-friendly error summary on failure — running the
150.     // test a second time just to capture output would double runtime/flakiness
